#!/bin/bash
set -e

echo "=================================================="
echo " Deploy: Fix Optometry edit-lock (Unlock to Edit"
echo " does nothing in embedded Doctor view)"
echo "=================================================="
echo ""
echo "Two related fixes, both in the Optometry Refraction"
echo "edit-lock chain:"
echo ""
echo "1) Near SPH/CYL/AXIS were permanently read-only"
echo "   (auto = Dist SPH + ADD), with no manual override."
echo "   Now editable again -- auto-fill still happens as a"
echo "   convenience default, but tapping always opens the"
echo "   picker."
echo ""
echo "2) ROOT CAUSE of \"can't edit anything after unlocking\":"
echo "   the doctor's \"Unlock to Edit\" button on a completed"
echo "   consultation only toggled an outer <fieldset"
echo "   disabled> wrapper. The embedded Optometry workspace"
echo "   fetches its OWN lock state from the server and sets"
echo "   every field's disabled= from THAT directly -- so"
echo "   unlocking the outer fieldset never reached it, and"
echo "   every Optometry field stayed disabled regardless."
echo "   Added a forceUnlocked prop so the page-level toggle"
echo "   now actually overrides it."
echo ""

TARGET="app/(main)/optometry/[id]/optometry-workspace.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

TARGET="app/consultation/[id]/consultation-form.js"
if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi
echo "Backing up $TARGET ..."
cp "$TARGET" "$TARGET.bak"
echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"
node --check "$TARGET" && echo "  Syntax OK: $TARGET"

echo ""
echo "Done. Review the diff with:"
echo '  git diff "app/(main)/optometry/[id]/optometry-workspace.js" "app/consultation/[id]/consultation-form.js"'
echo ""
echo "No DB migration needed -- client-code-only fix, applies"
echo "identically to production and training."
echo ""
echo "To fix Ashutosh Kumar Negi's existing record: after this"
echo "deploys, open his completed consultation as the doctor,"
echo "click \"Unlock to Edit\" (it will now actually work), go"
echo "to Optometry -> Final Rx tab, and enter the correct"
echo "Near RE SPH value directly."
